using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Buff 管理器 — 挂载到需要接收 Buff 的 GameObject 上。
/// 管理所有活跃 Buff 的生命周期（Apply / Tick / Remove）。
///
/// 用法: 挂载到 Player / Enemy Prefab 上，通过 ApplyBuff(BuffData) 添加 Buff。
/// </summary>
public class BuffManager : MonoBehaviour
{
    private readonly List<BuffInstance> _activeBuffs = new List<BuffInstance>();
    private readonly Dictionary<string, List<BuffInstance>> _buffDict = new Dictionary<string, List<BuffInstance>>();

    // 待移除队列 — 避免在迭代中修改集合
    private readonly List<BuffInstance> _pendingRemoval = new List<BuffInstance>();

    /// <summary>当前活跃 Buff 列表（只读）</summary>
    public IReadOnlyList<BuffInstance> ActiveBuffs => _activeBuffs;

    // ========== 事件 ==========

    /// <summary>Buff 被应用: (buff)</summary>
    public event Action<BuffInstance> OnBuffApplied;
    /// <summary>Buff 被移除: (buff)</summary>
    public event Action<BuffInstance> OnBuffRemoved;
    /// <summary>Buff 堆叠变化: (buff)</summary>
    public event Action<BuffInstance> OnBuffStackChanged;

    // ========== 核心方法 ==========

    /// <summary>
    /// 应用 Buff。如果同 ID Buff 已存在且可叠加，则尝试叠加；
    /// 否则创建新 BuffInstance。
    /// </summary>
    public BuffInstance ApplyBuff(BuffData data, GameObject caster = null)
    {
        if (data == null) return null;

        // 检查是否已有同 ID 的 Buff
        if (_buffDict.TryGetValue(data.buffId, out var existingList) && existingList.Count > 0)
        {
            var existing = existingList[0];

            // 可叠加且未满栈：叠加
            if (data.stackable && existing.CurrentStacks < data.maxStacks)
            {
                existing.AddStack();
                OnBuffStackChanged?.Invoke(existing);
                return existing;
            }

            // 不可叠加 / 已满栈：按叠加行为刷新或延长持续时间
            if (!data.isPermanent)
            {
                switch (data.stackBehavior)
                {
                    case StackBehavior.Refresh:
                        existing.RefreshDuration();
                        break;
                    case StackBehavior.ExtendDuration:
                        existing.ExtendDuration(data.duration);
                        break;
                    case StackBehavior.Independent:
                        // Independent 不可叠加时不刷新（保持独立计时）
                        break;
                }
                OnBuffStackChanged?.Invoke(existing);
            }
            return existing;
        }

        var buff = new BuffInstance(data, gameObject, caster);
        _activeBuffs.Add(buff);

        if (!_buffDict.ContainsKey(data.buffId))
            _buffDict[data.buffId] = new List<BuffInstance>();
        _buffDict[data.buffId].Add(buff);

        data.effect?.OnApply(gameObject, buff);
        OnBuffApplied?.Invoke(buff);
        return buff;
    }

    /// <summary>移除指定 Buff 实例</summary>
    public void RemoveBuff(BuffInstance buff)
    {
        if (buff == null || _pendingRemoval.Contains(buff)) return;
        _pendingRemoval.Add(buff);
    }

    /// <summary>移除指定 ID 的所有 Buff</summary>
    public void RemoveBuffById(string buffId)
    {
        if (_buffDict.TryGetValue(buffId, out var list))
        {
            for (int i = list.Count - 1; i >= 0; i--)
                RemoveBuff(list[i]);
        }
    }

    /// <summary>
    /// 清除所有可净化的 Debuff（排除 Indestructible 标记的藏品/道具 debuff）。
    /// 返回被清除的 debuff 数量。
    /// </summary>
    public int RemoveAllDebuffs()
    {
        var toRemove = new List<BuffInstance>();
        foreach (var buff in _activeBuffs)
        {
            if (buff == null) continue;
            if (buff.Data.buffType == BuffType.Debuff && !buff.Indestructible)
                toRemove.Add(buff);
        }

        foreach (var buff in toRemove)
            RemoveBuff(buff);

        return toRemove.Count;
    }

    /// <summary>是否有指定 Buff</summary>
    public bool HasBuff(string buffId) =>
        _buffDict.TryGetValue(buffId, out var list) && list.Count > 0;

    /// <summary>获取指定 ID 的第一个 Buff 实例</summary>
    public BuffInstance GetBuff(string buffId)
    {
        if (_buffDict.TryGetValue(buffId, out var list) && list.Count > 0)
            return list[0];
        return null;
    }

    /// <summary>获取指定 ID 的所有 Buff 实例</summary>
    public IReadOnlyList<BuffInstance> GetBuffs(string buffId)
    {
        if (_buffDict.TryGetValue(buffId, out var list))
            return list;
        return System.Array.Empty<BuffInstance>();
    }

    /// <summary>获取 Buff 堆叠总数（所有同 ID Buff 的堆叠和）</summary>
    public int GetBuffStackCount(string buffId)
    {
        int total = 0;
        if (_buffDict.TryGetValue(buffId, out var list))
        {
            foreach (var b in list)
                total += b.CurrentStacks;
        }
        return total;
    }

    // ========== Unity 生命周期 ==========

    private void Update()
    {
        float dt = Time.deltaTime;

        // Tick 所有活跃 Buff
        for (int i = _activeBuffs.Count - 1; i >= 0; i--)
        {
            var buff = _activeBuffs[i];
            if (buff.IsActive)
                buff.Tick(dt);
        }

        // 处理过期 Buff
        for (int i = _activeBuffs.Count - 1; i >= 0; i--)
        {
            if (!_activeBuffs[i].IsActive || _activeBuffs[i].IsExpired)
                _pendingRemoval.Add(_activeBuffs[i]);
        }

        // 执行待移除
        ProcessRemovalQueue();
    }

    private void ProcessRemovalQueue()
    {
        for (int i = 0; i < _pendingRemoval.Count; i++)
        {
            var buff = _pendingRemoval[i];
            if (buff == null) continue;

            buff.IsActive = false;
            buff.Data.effect?.OnRemove(gameObject, buff);
            _activeBuffs.Remove(buff);

            if (_buffDict.TryGetValue(buff.Data.buffId, out var list))
            {
                list.Remove(buff);
                if (list.Count == 0)
                    _buffDict.Remove(buff.Data.buffId);
            }

            OnBuffRemoved?.Invoke(buff);
        }
        _pendingRemoval.Clear();
    }

    private void OnDestroy()
    {
        // 清理所有 Buff
        for (int i = _activeBuffs.Count - 1; i >= 0; i--)
        {
            var buff = _activeBuffs[i];
            buff.Data.effect?.OnRemove(gameObject, buff);
        }
        _activeBuffs.Clear();
        _buffDict.Clear();
    }
}

using UnityEngine;

/// <summary>
/// 属性修改 Buff — 修改目标某个属性值。
/// 通过 StatModifier 支持加算/乘算/覆盖叠加。
///
/// 示例: "+30% 攻击力" → statName="AttackStrength", modifier={Multiplicative, 1.3f}
///        "+50 生命值" → statName="MaxHealth", modifier={Additive, 50f}
/// </summary>
[CreateAssetMenu(fileName = "StatBuff", menuName = "Game/Buff Effect/Stat")]
public class StatBuff : BuffEffectBase
{
    [Header("属性修改")]
    [Tooltip("属性名: MaxHealth / MoveSpeed / AttackStrength / BulletSpeed / ShotsPerMinute / ColliderRadius")]
    public string statName;

    [Tooltip("修改器（加算/乘算/覆盖 + 值）")]
    public StatModifier modifier;

    // 记录修改前的值，用于 OnRemove 恢复
    private float _originalValue;

    public override void OnApply(GameObject target, BuffInstance buff)
    {
        var stats = target.GetComponent<PlayerStats>();
        if (stats == null)
        {
            Debug.LogWarning($"StatBuff: target '{target.name}' 没有 PlayerStats 组件");
            return;
        }

        _originalValue = stats.GetStatValue(statName);
        float newValue = StatModifier.Apply(_originalValue, modifier);
        stats.SetStatValue(statName, newValue);
    }

    public override void OnRemove(GameObject target, BuffInstance buff)
    {
        var stats = target.GetComponent<PlayerStats>();
        if (stats == null) return;

        stats.SetStatValue(statName, _originalValue);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Buff 运行时实例 — 纯 C# class，非 MonoBehaviour。
/// 由 BuffManager 创建和管理生命周期。
/// 设计目标: 避免每个 Buff 创建 GameObject，统一由 BuffManager 的 Update 驱动 Tick。
/// </summary>
public class BuffInstance
{
    /// <summary>Buff 数据定义</summary>
    public BuffData Data { get; }

    /// <summary>挂载的目标 GameObject</summary>
    public GameObject Owner { get; }

    /// <summary>施放者（用于伤害归属等）</summary>
    public GameObject Caster { get; }

    /// <summary>当前堆叠数</summary>
    public int CurrentStacks { get; private set; } = 1;

    /// <summary>剩余持续时间（秒）</summary>
    public float RemainingDuration { get; private set; }

    /// <summary>已流逝时间（秒）</summary>
    public float ElapsedTime { get; private set; }

    /// <summary>是否已过期</summary>
    public bool IsExpired => !Data.isPermanent && RemainingDuration <= 0f;

    /// <summary>是否活跃</summary>
    public bool IsActive { get; set; } = true;

    /// <summary>不可清除标记（藏品/道具等来源的 buff，净化类技能不可清除）</summary>
    public bool Indestructible { get; set; }

    /// <summary>独立计时模式下每个堆叠的剩余时间</summary>
    private readonly List<float> _stackTimers = new List<float>();

    public BuffInstance(BuffData data, GameObject owner, GameObject caster)
    {
        Data = data;
        Owner = owner;
        Caster = caster;
        RemainingDuration = data.duration;
        _stackTimers.Add(data.duration);
    }

    /// <summary>添加堆叠</summary>
    public void AddStack()
    {
        if (!Data.stackable || CurrentStacks >= Data.maxStacks)
            return;

        switch (Data.stackBehavior)
        {
            case StackBehavior.Refresh:
                RemainingDuration = Data.duration;
                break;
            case StackBehavior.Independent:
                _stackTimers.Add(Data.duration);
                break;
            case StackBehavior.ExtendDuration:
                RemainingDuration += Data.duration;
                break;
        }
        CurrentStacks++;
    }

    /// <summary>刷新持续时间到初始值（Refresh 行为；供"在圈内停留持续刷新 debuff"场景使用）</summary>
    public void RefreshDuration()
    {
        RemainingDuration = Data.duration;
    }

    /// <summary>延长持续时间（ExtendDuration 行为）</summary>
    public void ExtendDuration(float amount)
    {
        RemainingDuration += amount;
    }

    /// <summary>直接设置剩余持续时间（偷取/转移 buff 等机制使用）</summary>
    public void SetRemainingDuration(float duration)
    {
        RemainingDuration = Mathf.Max(duration, 0f);
    }

    /// <summary>Tick — 由 BuffManager 调用</summary>
    public void Tick(float deltaTime)
    {
        if (!IsActive || Data.isPermanent)
            return;

        // Independent 模式：每帧 tick 所有独立堆叠
        if (Data.stackBehavior == StackBehavior.Independent)
        {
            for (int i = _stackTimers.Count - 1; i >= 0; i--)
            {
                _stackTimers[i] -= deltaTime;
                if (_stackTimers[i] <= 0f)
                {
                    _stackTimers.RemoveAt(i);
                    CurrentStacks--;
                }
            }
            RemainingDuration = _stackTimers.Count > 0 ? _stackTimers[^1] : -1f;
        }
        else
        {
            RemainingDuration -= deltaTime;
        }

        ElapsedTime += deltaTime;

        // 驱动效果 Tick
        Data.effect?.OnTick(Owner, this, deltaTime);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 玩家所有数值属性的唯一数据源。
/// PlayerController 和 PlayerCombat 通过引用读取所需属性。
/// </summary>
public class PlayerStats : MonoBehaviour, IDamageable, IHealable
{
    [Header("生命属性")]
    [SerializeField] private float maxHealth = 100f;
    [SerializeField] private float health = 100f;

    [Header("移动属性")]
    [SerializeField] private float moveSpeed = 5f;

    [Header("攻击属性")]
    [SerializeField] private float attackStrength = 10f;

    [Header("射击属性")]
    [SerializeField] private float bulletSpeed = 10f;
    [Tooltip("每分钟射击次数，300 = 每秒5发")]
    [SerializeField] private float shotsPerMinute = 300f;

    [Header("攻击乘区")]
    [Tooltip("攻击力乘区，真实攻击 = 基础攻击 × 此值")]
    [SerializeField] private float attackStrengthMultiplier = 1f;
    [Tooltip("射速乘区，真实射速 = 基础射速 × 此值")]
    [SerializeField] private float shotsPerMinuteMultiplier = 1f;

    [Header("碰撞属性")]
    [SerializeField] private float colliderRadius = 0.4f;

    [Header("进化倾向")]
    [Tooltip("进化倾向：正值=朝向宿主，负值=朝向独特。范围 -100 ~ 100")]
    [SerializeField] private float evolutionTendency = 0f;

    private bool _isDead = false;

    // ---------- 只读属性 ----------
    public float CurrentHealth => health;
    public float MaxHealth => maxHealth;
    public bool IsDead => _isDead;
    public float MoveSpeed => moveSpeed;
    public float AttackStrength => attackStrength * attackStrengthMultiplier;
    public float BulletSpeed => bulletSpeed;
    public float ShootCooldown => 60f / (shotsPerMinute * shotsPerMinuteMultiplier);
    public float ShotsPerMinute => shotsPerMinute * shotsPerMinuteMultiplier;
    public float ColliderRadius
    {
        get => colliderRadius;
        set => colliderRadius = Mathf.Max(value, 0.01f);
    }

    /// <summary>进化倾向：正值=朝向宿主（金色），负值=朝向独特（紫色）。范围 -100 ~ 100</summary>
    public float EvolutionTendency => evolutionTendency;

    // ---------- 委托 ----------
    /// <summary>生命变化委托：参数为 (当前生命, 最大生命)</summary>
    public event System.Action<float, float> OnHealthChanged;
    /// <summary>死亡委托</summary>
    public event System.Action OnDied;
    /// <summary>属性变化委托：参数为 (属性名)</summary>
    public event System.Action<string> OnStatChanged;

    private void Awake()
    {
        health = maxHealth;
    }

    // ---------- IDamageable ----------
    public void TakeDamage(float damage)
    {
        if (_isDead) return;

        // 无敌帧：免疫期间不受到任何伤害
        var immunity = GetComponent<DamageImmunity>();
        if (immunity != null && immunity.IsImmune) return;

        // 镇痛阻滞：伤害拆分为立即 + 延迟（延迟部分记入池，buff 结束后缓慢扣除）
        var analgesic = GetComponent<AnalgesicBlockRuntime>();
        if (analgesic != null && analgesic.IsActive)
            damage = analgesic.SplitDamage(damage);

        health -= damage;
        health = Mathf.Max(health, 0);

        // 弹出伤害数字（玩家受伤用红色）
        DamagePopup.Spawn(transform.position, damage, isPlayerDamage: true);

        // 角色受击 → 屏幕振动 + 全屏红闪
        if (CameraShake.Instance != null)
        {
            CameraShake.Instance.Shake(1f);
            CameraShake.Instance.FlashRed();
        }

#if UNITY_EDITOR
        Debug.Log($"玩家受击！剩余生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");

        if (health <= 0f)
        {
            Die();
        }
    }

    // ---------- IHealable ----------
    public void Heal(float amount)
    {
        if (_isDead) return;

        health = Mathf.Min(health + amount, maxHealth);

#if UNITY_EDITOR
        Debug.Log($"玩家治疗！当前生命：{health}");
#endif

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("Health");
    }

    private void Die()
    {
        _isDead = true;
        Debug.Log("玩家死亡");

        OnDied?.Invoke();
    }

    // ---------- Buff 系统属性读写接口 ----------

    /// <summary>通过属性名字符串获取当前值（供 Buff 系统使用）</summary>
    public float GetStatValue(string statName)
    {
        return statName switch
        {
            "MaxHealth"               => maxHealth,
            "Health"                  => health,
            "MoveSpeed"               => moveSpeed,
            "AttackStrength"          => attackStrength,
            "AttackStrengthMultiplier" => attackStrengthMultiplier,
            "BulletSpeed"             => bulletSpeed,
            "ShotsPerMinute"          => shotsPerMinute,
            "ShotsPerMinuteMultiplier" => shotsPerMinuteMultiplier,
            "ColliderRadius"          => colliderRadius,
            "EvolutionTendency"       => evolutionTendency,
            _                         => throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'")
        };
    }

    /// <summary>通过属性名字符串设置值，自动触发 OnStatChanged（供 Buff 系统使用）</summary>
    public void SetStatValue(string statName, float value)
    {
        switch (statName)
        {
            case "MaxHealth":
                maxHealth = Mathf.Max(value, 1f);
                health = Mathf.Min(health, maxHealth);
                break;
            case "Health":
                health = Mathf.Clamp(value, 0f, maxHealth);
                break;
            case "MoveSpeed":
                moveSpeed = Mathf.Max(value, 0f);
                break;
            case "AttackStrength":
                attackStrength = Mathf.Max(value, 0f);
                break;
            case "AttackStrengthMultiplier":
                attackStrengthMultiplier = Mathf.Max(value, 0f);
                break;
            case "BulletSpeed":
                bulletSpeed = Mathf.Max(value, 0f);
                break;
            case "ShotsPerMinute":
                shotsPerMinute = Mathf.Max(value, 0f);
                break;
            case "ShotsPerMinuteMultiplier":
                shotsPerMinuteMultiplier = Mathf.Max(value, 0f);
                break;
            case "ColliderRadius":
                colliderRadius = Mathf.Max(value, 0.01f);
                break;
            case "EvolutionTendency":
                evolutionTendency = Mathf.Clamp(value, -100f, 100f);
                break;
            default:
                throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'");
        }
        OnStatChanged?.Invoke(statName);
    }

    // ---------- 科技树 / 配置接口 ----------

    /// <summary>应用基础配置值（来自 PlayerConfig SO）</summary>
    public void ApplyBaseStats(PlayerConfig config)
    {
        if (config == null) return;

        maxHealth = config.maxHealth;
        moveSpeed = config.moveSpeed;
        attackStrength = config.attackStrength;
        bulletSpeed = config.bulletSpeed;
        shotsPerMinute = config.shotsPerMinute;
        colliderRadius = config.colliderRadius;
        health = maxHealth; // 重置满血

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("All");
    }

    /// <summary>叠加科技树加成（在 ApplyBaseStats 之后调用）</summary>
    public void ApplyBonuses(Dictionary<string, float> bonuses)
    {
        if (bonuses == null || bonuses.Count == 0) return;

        foreach (var kvp in bonuses)
        {
            SetStatValue(kvp.Key, GetStatValue(kvp.Key) + kvp.Value);
        }

        // 加成后恢复满血（生命上限可能增加了）
        if (bonuses.ContainsKey("MaxHealth"))
            health = maxHealth;

        OnHealthChanged?.Invoke(health, maxHealth);
        OnStatChanged?.Invoke("All");
    }

    // ---------- 数值修正 ----------
    private void OnValidate()
    {
        health = Mathf.Clamp(health, 0, maxHealth);
        maxHealth = Mathf.Max(maxHealth, 1f);
        moveSpeed = Mathf.Max(moveSpeed, 0);
        attackStrength = Mathf.Max(attackStrength, 0);
        attackStrengthMultiplier = Mathf.Max(attackStrengthMultiplier, 0f);
        bulletSpeed = Mathf.Max(bulletSpeed, 0f);
        shotsPerMinute = Mathf.Max(shotsPerMinute, 1f);
        shotsPerMinuteMultiplier = Mathf.Max(shotsPerMinuteMultiplier, 0f);
        colliderRadius = Mathf.Max(colliderRadius, 0.01f);
        evolutionTendency = Mathf.Clamp(evolutionTendency, -100f, 100f);
    }
}

