    /// <summary>閬撳叿鑾峰緱: (itemData)</summary>
    public event Action<ItemData> OnItemAcquired;

    /// <summary>閬撳叿绉婚櫎: (itemData)</summary>
    public event Action<ItemData> OnItemRemoved;

    /// <summary>閬撳叿涓㈠純: (itemData, worldPosition)</summary>
