///   3. 閫氱煡浜嬩欢锛堜緵 UI Controller 鐩戝惉锛?
/// </summary>
public class ItemManager : MonoBehaviour
{
    [Header("涓㈠純閰嶇疆")]
    [SerializeField] private GameObject _itemDropPrefab; // 涓㈠純閬撳叿鏃剁敓鎴愮殑鎷惧彇鐗╅鍒朵綋

    [Header("璋冭瘯")]
