    switch (statName)
    {
        case "MaxHealth":
            maxHealth = Mathf.Max(value, 1f);
            health = Mathf.Min(health, maxHealth);
            break;
        case "Health":
            health = Mathf.Clamp(value, 0f, maxHealth);
            break;
        case "MoveSpeed": moveSpeed = Mathf.Max(value, 0f); break;
        case "AttackStrength": attackStrength = Mathf.Max(value, 0f); break;
        case "AttackStrengthMultiplier": attackStrengthMultiplier = Mathf.Max(value, 0f); break;
        case "BulletSpeed": bulletSpeed = Mathf.Max(value, 0f); break;
        case "ShotsPerMinute": shotsPerMinute = Mathf.Max(value, 0f); break;
        case "ShotsPerMinuteMultiplier": shotsPerMinuteMultiplier = Mathf.Max(value, 0f); break;
        case "ColliderRadius": colliderRadius = Mathf.Max(value, 0.01f); break;
        case "EvolutionTendency": evolutionTendency = Mathf.Clamp(value, -100f, 100f); break;
        default:
            throw new System.ArgumentException($"PlayerStats: 未知属性名 '{statName}'");
    }
    OnStatChanged?.Invoke(statName);
}
